mapper.select:
        SELECT BOOKSET_ID code,BOOKSET_NAME name,BOOKSET_NAME shortName,BOOKSET_ID hidCode FROM BOK_BOOKSET
        where 1=1

        		AND	BOOKSET_TYPE = #{booksetType}


        	AND	(BOOKSET_ID like concat('%',concat(#{param},'%'))
        		OR BOOKSET_NAME like concat('%',concat(#{param},'%')))


	        	AND (BOOKSET_ID in 


	                	null) or BOOKSET_ID in (

                	#{item}

            	)

        order by bookset_type,BOOKSET_ID

SELECT BOOKSET_ID id,BOOKSET_NAME text FROM BOK_BOOKSET where 1=1 and BOOKSET_TYPE in ('02','03')
AND BOOKSET_TYPE != #{noBooksetType}
AND BOOKSET_TYPE = #{booksetType}
AND (BOOKSET_ID like concat('%',concat(#{search},'%')) OR BOOKSET_NAME like concat('%',concat(#{search},'%')))
order by bookset_type,BOOKSET_ID

SELECT * FROM ( SELECT BOOKSET_ID id,BOOKSET_NAME text,BOOKSET_TYPE FROM BOK_BOOKSET
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID = REPLACE(BOK_BOOKSET.BOOKSET_ID,'F16_','') AND USER_ID = #{userId}
where 1=1 AND ACCT_SUBJECT_TYPE != 'F26' AND BOOKSET_TYPE != '01'
AND BOOKSET_ID_TMPL = #{booksetIdTmpl}
AND (BOOKSET_ID like concat('%',concat(#{search},'%')) OR BOOKSET_NAME like concat('%',concat(#{search},'%')))
UNION ALL SELECT BOOKSET_ID id,BOOKSET_NAME text,BOOKSET_TYPE FROM BOK_BOOKSET where 1=1 AND ACCT_SUBJECT_TYPE = 'F26' AND BOOKSET_TYPE != '01'
AND BOOKSET_ID_TMPL = #{booksetIdTmpl}
AND (BOOKSET_ID like concat('%',concat(#{search},'%')) OR BOOKSET_NAME like concat('%',concat(#{search},'%')))
) order by bookset_type,id

SELECT A.BOOKSET_ID AS booksetId, A.BOOKSET_NAME AS booksetName, A.BOOKSET_TYPE AS booksetType, A.BOOKSET_TYPE AS booksetTypeCode, A.ACCT_SUBJECT_ID AS acctSubjectId, A.STANDARD_CCY AS standardCcy, A.STANDARD_CCY AS standardCcyCode, A.ACCT_SUBJECT_TYPE AS acctSubjectType, A.BOOKSET_ID_TMPL AS booksetIdTmpl, B.ACCT_STANDARD_NAME AS acctStandard, A.START_DATE AS startDate, A.END_DATE AS endDate FROM BOK_BOOKSET A LEFT JOIN bok_ACCT_STANDARD B ON B.ACCT_STANDARD_ID=A.ACCT_STANDARD WHERE ACCT_SUBJECT_TYPE NOT IN ('F16','F18') AND BOOKSET_TYPE=#{booksetType} and BOOKSET_TYPE in ('02','03')
AND BOOKSET_Id in
#{item}
union all SELECT A.BOOKSET_ID AS booksetId, A.BOOKSET_NAME AS booksetName, A.BOOKSET_TYPE AS booksetType, A.BOOKSET_TYPE AS booksetTypeCode, A.ACCT_SUBJECT_ID AS acctSubjectId, A.STANDARD_CCY AS standardCcy, A.STANDARD_CCY AS standardCcyCode, A.ACCT_SUBJECT_TYPE AS acctSubjectType, A.BOOKSET_ID_TMPL AS booksetIdTmpl, B.ACCT_STANDARD_NAME AS acctStandard, A.START_DATE AS startDate, A.END_DATE AS endDate FROM BOK_BOOKSET A LEFT JOIN bok_ACCT_STANDARD B ON B.ACCT_STANDARD_ID=A.ACCT_STANDARD
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID = REPLACE(A.BOOKSET_ID,'F16_','') AND USER_ID = #{userId}
WHERE ACCT_SUBJECT_TYPE IN ('F16','F18') AND BOOKSET_TYPE=#{booksetType} and BOOKSET_TYPE in ('02','03')
AND BOOKSET_Id in
#{item}

SELECT * FROM ( SELECT BOOKSET_ID id,BOOKSET_NAME text,BOOKSET_TYPE FROM BOK_BOOKSET
AND ACCT_SUBJECT_TYPE NOT IN ('F16','F18')
AND BOOKSET_TYPE = #{booksetType}
AND (BOOKSET_ID like concat('%',concat(#{search},'%')) OR BOOKSET_NAME like concat('%',concat(#{search},'%')))
UNION ALL SELECT BOOKSET_ID id,BOOKSET_NAME text,BOOKSET_TYPE FROM BOK_BOOKSET
INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID = REPLACE(BOK_BOOKSET.BOOKSET_ID,'F16_','') AND USER_ID = #{userId}
AND ACCT_SUBJECT_TYPE IN ('F16','F18')
AND BOOKSET_TYPE = #{booksetType}
AND (BOOKSET_ID like concat('%',concat(#{search},'%')) OR BOOKSET_NAME like concat('%',concat(#{search},'%')))
) order by bookset_type,id

SELECT A.BOOKSET_ID AS booksetId, A.BOOKSET_NAME AS booksetName, A.BOOKSET_TYPE AS booksetType, A.BOOKSET_TYPE AS booksetTypeCode, A.ACCT_SUBJECT_ID AS acctSubjectId, A.STANDARD_CCY AS standardCcy, A.STANDARD_CCY AS standardCcyCode, A.ACCT_SUBJECT_TYPE AS acctSubjectType, A.BOOKSET_ID_TMPL AS booksetIdTmpl, B.ACCT_STANDARD_NAME AS acctStandard, A.START_DATE AS startDate, A.END_DATE AS endDate FROM BOK_BOOKSET A LEFT JOIN bok_ACCT_STANDARD B ON B.ACCT_STANDARD_ID=A.ACCT_STANDARD WHERE BOOKSET_TYPE=#{booksetType} and BOOKSET_TYPE ='01'
AND BOOKSET_Id in
#{item}

SELECT BOOKSET_ID id,BOOKSET_NAME text FROM BOK_BOOKSET where 1=1 and BOOKSET_TYPE ='01'
AND BOOKSET_TYPE != #{noBooksetType}
AND BOOKSET_TYPE = #{booksetType}
AND (BOOKSET_ID like concat('%',concat(#{search},'%')) OR BOOKSET_NAME like concat('%',concat(#{search},'%')))
order by bookset_type,BOOKSET_ID
